"""Quick Beam Service mode functions. These functions are called from the
top level IntegrityService interface. They are not intended to be called
directly from a test script"""

import interops.libraries.integrity.integrity_objects as IntegrityObjects
import interops.libraries.integrity.pages.service_screen as ServicePgObj
import interops.libraries.integrity.pages.quickbeam_menu as QuickBeamPgObj
from interops.libraries.integrity.beam_data import Beam
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import INTEGRITY_APP_NAME
import squishtest3 as sq
import logging


logger = logging.getLogger(__name__)

@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_funcs_open_quick_beam_menu() -> bool:
    '''
    Opens the Quick Beam Menu page from the main
    Service Menu Bar via the Service Functions menu.

    Returns:
        bool - True if Quick Beam Menu opened successfully
    '''
    for n in range(2):
        try:
            logger.info("open_quick_beam_menu called.")

            service_menu = ServicePgObj.ServiceMenuBar()
            if service_menu.ready():
                service_menu.service_functions()
                sq.snooze(1)
                service_funcs_menu = ServicePgObj.ServiceFunctionsMenuBar()
                service_funcs_menu.deliver_quick_beam()
                try:
                    sq.waitForObject("{text='Radiation'  type='TabItem'}")
                except Exception:
                    sq.waitForObject({"id": 6})
                return True
        except Exception:
            logger.info("open_quick_beam_menu failed.")
            pass
    return False


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_open_quick_beam_menu():
    '''
    Opens the Deliver Quick Beam Menu page assuming the
    Service Functions menu is already open
    '''
    service_funcs_menu = ServicePgObj.ServiceFunctionsMenuBar()
    service_funcs_menu.deliver_quick_beam()


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_setup_quick_beam_radiation(beam: Beam) -> None:
    '''
    Set up the beam values and maximum dose rate for a Deliver Quick Beam.

    Args:
        beam (Beam): Beam object with energy, beam_mu1, beam_mu2 and max_dose_rate set.

    '''
    logger.info("setup_deliver_beam_radiation called: " + str(beam))

    quick_beam_menu = QuickBeamPgObj.DeliverQuickBeam()
    if quick_beam_menu.ready():
        quick_beam_menu.tab_mlc()
        quick_beam_menu.press_square_rect()

        shapes = quick_beam_menu.Shapes()
        shapes.press_ok()
        quick_beam_menu.tab_radiation()
        quick_beam_menu.set_energy(beam.beam_energy)
        quick_beam_menu.set_beam_mu1(beam.beam_mu1)
        quick_beam_menu.set_beam_mu2(beam.beam_mu2)
        if beam.max_dose_rate:
            quick_beam_menu.set_max_dose_rate(beam.max_dose_rate)
        sq.snooze(3)


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_select_confirm_deliver_quickbeam() -> bool:
    '''
    Confirms the selection of a beam on Deliver Quick Beam page

    Returns:
        bool - True if Quick Beam confirmed
    '''
    try:
        quick_beam_menu = QuickBeamPgObj.DeliverQuickBeam()
        quick_beam_menu.press_confirm()
        return sq.waitForObject(IntegrityObjects.dQB_Btn_Unconfirm)["enabled"]
    except Exception as e:
        logger.exception("confirm_deliver_quickbeam exception " + str(e))
        return False


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_select_unconfirm_deliver_quickbeam() -> bool:
    '''
    Unconfirms a beam on the Deliver Quick Beam page.

    Returns:
        bool - True if Quick Beam unconfirmed
    '''
    try:
        quick_beam_menu = QuickBeamPgObj.DeliverQuickBeam()
        quick_beam_menu.press_unconfirm()
        return sq.waitForObject(":DQB_Button_Confirm")["enabled"]
    except Exception as e:
        logger.exception("unconfirm_deliver_quickbeam exception " + str(e))
        return False


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_close_deliver_quickbeam() -> None:
    '''
    Closes the Deliver Quick Beam page.
    '''
    quick_beam_menu = QuickBeamPgObj.DeliverQuickBeam()
    quick_beam_menu.press_close()


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_quick_beam_press_next_beam() -> None:
    '''
    Selects the next beam on the Deliver Quick Beam UI.
    '''
    quick_beam_menu = QuickBeamPgObj.DeliverQuickBeam()
    quick_beam_menu.press_next_beam()
    sq.snooze(2)